mapper.sql:
WHERE h.DELETED_YN = 'N'
AND h.PROGRESS_STATUS = #{progressStatus}
AND EXISTS ( SELECT 1 FROM SHIP_INSTRUCTION_LINE search_line WHERE search_line.SHIP_INSTRUCTION_ID = h.SHIP_INSTRUCTION_ID AND search_line.DELETED_YN = 'N' AND UPPER(search_line.ITEM_NAME) LIKE '%' || UPPER(#{keyword}) || '%' )

mapper.update:
UPDATE SHIP_INSTRUCTION_LINE
SET SALE_LINE_ID =
#{saleLineId}, ITEM_ID = #{itemId}, ITEM_NAME = #{itemName},
SPECIFICATION = #{specification}, UNIT = #{unit},
QUANTITY =
#{quantity}, NOTE = #{note}
WHERE SHIP_INSTRUCTION_LINE_ID =
#{shipInstructionLineId}
AND SHIP_INSTRUCTION_ID = #{shipInstructionId}
AND DELETED_YN = 'N'
